head.script:
scwin.onpageload = function() {
    //if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");} //팝업을 사용하기 위해 반드시 포함되어야 한다.
    var jsonData = [{
        "col1": 1234,
        "col2": "aaaa"
    }, {
        "col1": 5678,
        "col2": "bbbb"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.popup_callbackFn = function(e) {
    console.log("callback Function");
    alert("팝업 closeAction 함수");
    return true;
}
scwin.trigger1_onclick = function(e) {
    console.log("trigger1_onclick: ", e);
    console.log(e.target.offsetTop, e.target.offsetLeft, e.clientX, e.clientY);
    //var url="./openPopup_gridView.xml";
    //var url="./openPopup_upload.xml";
    //      var url="/bangsa/gridView_subTotal_footer_2.xml";
    var url = "popup_closePopup_not_close_WESD-168_(WSQ-4329)_popup.xml";
    // var url="/WebSquare10.xml";
    var jsonObj = dataList1.getAllJSON();
    var dataObj = {
        type: "json",
        data: {
            fileName: "file.mrd",
            parent_dataList: jsonObj,
            callbackFn: "scwin.popup_callbackFn"
        },
        name: "paramObj"
    };
    var options = {
        id: "popup1"
            // , type: "wframePopup"
            ,
        type: "browserPopup",
        width: "300px",
        height: "445px",
        top: e.target.offsetTop + 20,
        left: e.target.offsetLeft + e.target.offsetWidth + 20
            //, useIframe: false
            ,
        dataObject: dataObj
            // , modal: true
            // , useModalStack: true
            ,
        useATagBtn: true,
        alwaysOnTop: true
        // , useModalDisable: true  // modal true 시 부모영역 컴포넌트 disabled 처리 유무
        // , closeAction: "scwin.popup_callbackFn"
    };
    //debugger;
    $p.openPopup(url, options, dataObj);
    var _top = e.target.offsetTop + 20;
    var _left = e.target.offsetLeft + e.target.offsetWidth + 20;
    var url1 = "/WebSquare10.xml"
    var _url = "/websquare/popup.html?w2xPath=" + url1 + "&popupID=" + "popup1";
    // window.open(_url, "_blank", "width=247px,height=245px,top="+_top+",left="+_left);
};
scwin.trigger2_onclick = function(e) {
    console.log("trigger2 onclick");
    var popObj = $p.getPopupWindow("popup1");
    if (popObj) popObj.document.title = "변경된 팝업 타이틀";
};
scwin.trigger2_onmousedown = function(e) {
    console.log("trigger2 onmousedown");
};
